    fn valid_pi_theme_json(name: &str) -> String {
        let mut colors = serde_json::Map::new();
        for token in [
            "accent",
            "border",
            "borderAccent",
            "borderMuted",
            "success",
            "error",
            "warning",
            "muted",
            "dim",
            "text",
            "thinkingText",
            "selectedBg",
            "userMessageBg",
            "userMessageText",
            "customMessageBg",
            "customMessageText",
            "customMessageLabel",
            "toolPendingBg",
            "toolSuccessBg",
            "toolErrorBg",
            "toolTitle",
            "toolOutput",
            "mdHeading",
            "mdLink",
            "mdLinkUrl",
            "mdCode",
            "mdCodeBlock",
            "mdCodeBlockBorder",
            "mdQuote",
            "mdQuoteBorder",
            "mdHr",
            "mdListBullet",
            "toolDiffAdded",
            "toolDiffRemoved",
            "toolDiffContext",
            "syntaxComment",
            "syntaxKeyword",
            "syntaxFunction",
            "syntaxVariable",
            "syntaxString",
            "syntaxNumber",
            "syntaxType",
            "syntaxOperator",
            "syntaxPunctuation",
            "thinkingOff",
            "thinkingMinimal",
            "thinkingLow",
            "thinkingMedium",
            "thinkingHigh",
            "thinkingXhigh",
            "bashMode",
        ] {
            colors.insert(token.to_string(), json!("#223344"));
        }
        colors.insert("accent".to_string(), json!("brand"));
        colors.insert("borderAccent".to_string(), json!("brandSoft"));
        colors.insert("muted".to_string(), json!(242));
        colors.insert("text".to_string(), json!(""));
        colors.insert("warning".to_string(), json!("warn"));
        colors.insert("selectedBg".to_string(), json!("#111111"));
        colors.insert("permissionAutoReviewingBg".to_string(), json!("brand"));
        colors.insert("permissionAutoApprovedBg".to_string(), json!("#002200"));
        colors.insert("permissionAutoDeniedBg".to_string(), json!("#220000"));
        json!({
            "name": name,
            "vars": {
                "brand": "#123abc",
                "brandSoft": "brand",
                "warn": 220,
                "page": "#010203"
            },
            "colors": colors,
            "export": {
                "pageBg": "page",
                "cardBg": "#0a0b0c"
            }
        })
        .to_string()
    }

